# ──────────────────────────────────────────────────────────────────────
# DOWNLOAD LOGIC
# ──────────────────────────────────────────────────────────────────────

LOGO_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "logos")

SOURCES = [
    "https://logo.clearbit.com/{domain}?size=200",
    "https://img.logo.dev/{domain}?token=pk_anonymous&size=200&format=png",
    "https://www.google.com/s2/favicons?domain={domain}&sz=128",
]


def download_logo(ticker, domain):
    """Download logo for a ticker. Try multiple sources."""
    path = os.path.join(LOGO_DIR, f"{ticker}.png")
    if os.path.exists(path) and os.path.getsize(path) > 500:
        return "exists"

    for url_template in SOURCES:
        url = url_template.format(domain=domain)
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
            })
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = resp.read()
                if len(data) > 500:  # Skip tiny/broken images
                    with open(path, "wb") as f:
                        f.write(data)
                    return "ok"
        except Exception:
            pass
        time.sleep(0.15)

    return "fail"


def main():
    os.makedirs(LOGO_DIR, exist_ok=True)
    total = len(companies)
    results = {"ok": 0, "exists": 0, "fail": 0}
    failures = []

    for i, (ticker, domain) in enumerate(sorted(companies.items()), 1):
        status = download_logo(ticker, domain)
        results[status] += 1
        if status == "fail":
            failures.append(ticker)
        symbol = {"ok": "✓", "exists": "·", "fail": "✗"}[status]
        print(f"[{i:4d}/{total}] {symbol} {ticker:<12} {domain}")

    print(f"\nDone: {results['ok']} new + {results['exists']} existing = {results['ok']+results['exists']}/{total}")
    if failures:
        print("Failed (" + str(len(failures)) + "): " + ", ".join(failures))


if __name__ == "__main__":
    main()
